import { z } from "zod";

/**
 * The annotation record for one public lease (evals/lease-corpus/annotations/).
 *
 * The committed records hold metadata and empty review slots only: no lease
 * text and no labels. Two reviewers fill their own `reviews` entry
 * independently, before seeing any Blueline output for that document. An
 * adjudicator then resolves every disagreement. Nothing generated by a model
 * may be entered as a label (ADR 0012).
 */

export const RISK_CATEGORIES = ["deposit", "early-exit", "dispute-rights", "auto-renewal", "rent-change", "other", "none"] as const;
export const MATERIALITY = ["material", "ordinary", "harmless-oddity", "borderline"] as const;

export const annotationItemSchema = z.strictObject({
  itemId: z.string().min(1),
  /** Copied from the extracted text exactly, character for character. */
  quotedSentence: z.string().min(1),
  expectedRiskCategory: z.enum(RISK_CATEGORIES),
  consequence: z.string(),
  triggeringCondition: z.string(),
  materiality: z.enum(MATERIALITY),
  /** Null when the clause isn't material. */
  expectedSeverity: z.enum(["high", "medium", "low"]).nullable(),
  /** Should Blueline flag this sentence? */
  reviewerDecision: z.enum(["flag", "do-not-flag"]),
  rationale: z.string().min(1),
});

const reviewSchema = z.strictObject({
  /** Pseudonymous; real identities and consent stay in private storage. */
  reviewerId: z.string().min(1).nullable(),
  completedBeforeSeeingModelOutput: z.boolean().nullable(),
  completedOn: z.string().nullable(),
  items: z.array(annotationItemSchema),
});

const availableRecordSchema = z.strictObject({
  documentId: z.string(),
  sourceUrl: z.string().url(),
  accessedOn: z.string(),
  available: z.literal(true),
  label: z.string(),
  sha256Original: z.string().length(64),
  sha256Text: z.string().length(64),
  textIsDerived: z.boolean(),
  jurisdiction: z.string(),
  housingContext: z.string(),
  programRestrictions: z.string(),
  documentType: z.string(),
  isTemplateNotExecutedLease: z.boolean(),
  completeness: z.strictObject({
    status: z.enum(["complete-as-supplied", "incomplete-as-supplied", "unclear-as-supplied", "partial-excerpt"]),
    observed: z.string(),
    needsHumanCheck: z.array(z.string()),
  }),
  usageRights: z.string(),
  proposedSplit: z.enum(["development", "holdout-candidate", "holdout-locked"]),
  exposureToPromptWork: z.array(z.string()),
  requiresHumanReview: z.boolean(),
  reviews: z.tuple([reviewSchema, reviewSchema]),
  adjudication: z.strictObject({
    status: z.enum(["not-started", "in-progress", "resolved"]),
    adjudicatorId: z.string().min(1).nullable(),
    /** The agreed label for each item, after disagreements are resolved. */
    resolvedItems: z.array(annotationItemSchema.extend({ disagreement: z.boolean() })),
    notes: z.string().nullable(),
  }),
});

const unavailableRecordSchema = z.strictObject({
  documentId: z.string(),
  sourceUrl: z.string().url(),
  accessedOn: z.string(),
  available: z.literal(false),
  label: z.string(),
  status: z.literal("unavailable"),
  note: z.string(),
  proposedReplacement: z.string(),
  replacementApproved: z.boolean(),
});

export const annotationRecordSchema = z.union([availableRecordSchema, unavailableRecordSchema]);
export type AnnotationRecord = z.infer<typeof annotationRecordSchema>;

/**
 * Problems that stop a record being used as evaluation evidence. A record
 * with no reviews yet has none of these; it is simply not ready.
 */
export function validateRecord(record: AnnotationRecord, text: string | null): string[] {
  if (!record.available) return [];
  const problems: string[] = [];
  const check = (where: string, sentence: string) => {
    if (text === null) return;
    const first = text.indexOf(sentence);
    if (first < 0) problems.push(`${where}: quote not found in the text`);
    else if (text.indexOf(sentence, first + 1) >= 0) problems.push(`${where}: quote appears more than once; quote a longer, unique span`);
  };
  record.reviews.forEach((review, index) => {
    if (review.items.length === 0) return;
    if (!review.reviewerId) problems.push(`review ${index + 1}: items without a reviewer id`);
    if (review.completedBeforeSeeingModelOutput !== true) problems.push(`review ${index + 1}: not confirmed as completed before seeing model output`);
    review.items.forEach((item) => {
      check(`review ${index + 1} ${item.itemId}`, item.quotedSentence);
      if (item.materiality !== "material" && item.expectedSeverity !== null) problems.push(`review ${index + 1} ${item.itemId}: severity given for a clause not judged material`);
    });
  });
  const [first, second] = record.reviews;
  if (first.reviewerId && second.reviewerId && first.reviewerId === second.reviewerId) {
    problems.push("both reviews have the same reviewer id; they must be independent");
  }
  if (record.adjudication.status === "resolved") {
    if (!record.adjudication.adjudicatorId) problems.push("adjudication resolved without an adjudicator id");
    if (first.items.length === 0 || second.items.length === 0) problems.push("adjudication resolved before both reviews were complete");
    record.adjudication.resolvedItems.forEach((item) => check(`adjudicated ${item.itemId}`, item.quotedSentence));
  }
  return problems;
}

/** Where a record stands on the way to being independent evidence. */
export function readiness(record: AnnotationRecord): string {
  if (!record.available) return record.replacementApproved ? "replacement approved, not yet fetched" : "unavailable; replacement needs owner approval";
  const done = record.reviews.filter((review) => review.items.length > 0 && review.reviewerId).length;
  if (record.adjudication.status === "resolved") return "adjudicated";
  if (done === 2) return "both reviews in; adjudication pending";
  if (done === 1) return "one review in";
  return "awaiting reviewers";
}
